function canonicalValue(value: unknown): string {
  if (Array.isArray(value)) return "[" + value.map(canonicalValue).join(",") + "]";
  if (value && typeof value === "object") {
    const fields = value as Record<string, unknown>;
    return "{" + Object.keys(fields).sort().map(key => JSON.stringify(key) + ":" + canonicalValue(fields[key])).join(",") + "}";
  }
  return JSON.stringify(value) ?? "undefined";
}

/** Immutable provider facts/counts must match admission. Distance and spatial
 * relation are independently recomputed for the exact supplied anchor/AOI by
 * the strict parser; neither is allowed to replace an admitted coordinate. */
export function independentFactsMatchAdmission(value: IndependentPointObjectContext): boolean {
  const admitted = value.caseId ? pinnedCases[value.caseId] : null;
  if (!admitted || value.sampleSize !== admitted.sampleSize ||
      value.interiorSampleSize !== admitted.interiorSampleSize ||
      value.places.length !== admitted.ids.length) return false;
  const ids = new Set(value.places.map(place => place.id));
  if (ids.size !== admitted.ids.length || admitted.ids.some(id => !ids.has(id))) return false;
  return value.places.every(place => {
    const { distanceM: _distance, relation: _relation, ...facts } = place;
    return Object.prototype.hasOwnProperty.call(pinnedRecords, place.id) &&
      canonicalValue(facts) === canonicalValue(pinnedRecords[place.id]);
  });
}

